 static final String EMPTY="No active audio sessions detected";
 final Context c;final ShortcutRepository prefs;final MediaSessionManager manager;final Handler h=new Handler(Looper.getMainLooper());final ExecutorService images=new ThreadPoolExecutor(1,1,0L,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<Runnable>(1),new ThreadPoolExecutor.DiscardOldestPolicy());final Set<Listener> listeners=new LinkedHashSet<>();final Map<MediaSession.Token,MediaController> controllers=new LinkedHashMap<>();final Map<MediaSession.Token,MediaController.Callback> callbacks=new HashMap<>();final Map<String,Boolean> wasPlaying=new HashMap<>();final Map<MediaSession.Token,String> ids=new HashMap<>();int nextId,leases;volatile int generation;boolean registered;String selected="",notice="";MediaController controller;Bitmap artwork;String source="",title="",detail="";PlaybackState playback;
