 boolean authorized(){String list=Settings.Secure.getString(c.getContentResolver(),"enabled_notification_listeners");ComponentName me=new ComponentName(c,AudioSessionBridge.class);if(list!=null)for(String s:list.split(":"))if(me.equals(ComponentName.unflattenFromString(s)))return true;return false;}
