 void disconnect(){if(registered&&manager!=null)try{manager.removeOnActiveSessionsChangedListener(sessions);}catch(RuntimeException ignored){}registered=false;for(MediaSession.Token t:new ArrayList<>(controllers.keySet()))unregister(t);wasPlaying.clear();selected="";controller=null;playback=null;source=title=detail="";artwork=null;generation++;emit();}
